struct Node
{
    int value;
    Node* next;
};

void pushFront(Node*& head, int value)
{
    head = new Node{ value, head };
}

int size(const Node* head)
{
    int count{ 0 };
    for (const Node* n{ head }; n != nullptr; n = n->next) ++count;
    return count;
}

int removeAll(Node*& head, int value)
{
    int removed{ 0 };
    Node** link{ &head };
    while (*link != nullptr)
    {
        if ((*link)->value == value)
        {
            Node* dead{ *link };
            *link = dead->next;      // skip it; link stays put, now pointing at the next node
            delete dead;
            ++removed;
        }
        else
        {
            link = &(*link)->next;   // move on to the next link
        }
    }
    return removed;
}

void clear(Node*& head)
{
    while (head != nullptr)
    {
        Node* next{ head->next };
        delete head;
        head = next;
    }
}

