#include <vector>
static std::vector<int> values(const Node* head) { std::vector<int> out; for (const Node* n{ head }; n; n = n->next) out.push_back(n->value); return out; }
TEST("push to the front")
{
    Node* head{ nullptr };
    pushFront(head, 3); pushFront(head, 2); pushFront(head, 1);
    CHECK(values(head) == std::vector<int>({ 1, 2, 3 }));
    CHECK_EQ(size(head), 3);
    clear(head);
    CHECK(head == nullptr);
}
TEST("an empty list") { Node* head{ nullptr }; CHECK_EQ(size(head), 0); CHECK_EQ(removeAll(head, 1), 0); clear(head); CHECK(head == nullptr); }
TEST("remove from the middle")
{
    Node* head{ nullptr };
    for (int v : { 4, 7, 9 }) pushFront(head, v);          // 9 7 4
    CHECK_EQ(removeAll(head, 7), 1);
    CHECK(values(head) == std::vector<int>({ 9, 4 }));
    clear(head);
}
TEST("remove the head and the tail")
{
    Node* head{ nullptr };
    for (int v : { 1, 2, 1 }) pushFront(head, v);          // 1 2 1
    CHECK_EQ(removeAll(head, 1), 2);
    CHECK(values(head) == std::vector<int>({ 2 }));
    clear(head);
}
TEST("remove neighbours")
{
    Node* head{ nullptr };
    for (int v : { 5, 5, 5, 6, 5 }) pushFront(head, v);    // 5 6 5 5 5
    CHECK_EQ(removeAll(head, 5), 4);
    CHECK(values(head) == std::vector<int>({ 6 }));
    clear(head);
}
TEST("remove everything") { Node* head{ nullptr }; pushFront(head, 8); pushFront(head, 8); CHECK_EQ(removeAll(head, 8), 2); CHECK(head == nullptr); }
TEST("no leaks")
{
    CHECK_NO_LEAK({
        Node* head{ nullptr };
        for (int i{ 0 }; i < 50; ++i) pushFront(head, i % 3);
        removeAll(head, 1);
        clear(head);
    });
}

